{
  "schemaVersion": "0.2",
  "slug": "ticker",
  "name": "Ticker",
  "family": "F",
  "status": "experimental",
  "purpose": "Shows a horizontally scrolling strip of compact market or status items.",
  "scenarios": [
    "Stock price strip",
    "Live system status feed",
    "Exchange rate ribbon"
  ],
  "props": {
    "items": {
      "type": "string",
      "required": true,
      "description": "Array of { id, label, value, trend? } ticker entries."
    },
    "label": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the ticker region."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Ticker populated with items."
    },
    {
      "name": "empty",
      "description": "No items provided."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "app-shell"
    ],
    "allowedChildren": [
      "text"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not animate the strip without honoring reduced motion.",
    "Do not place interactive controls inside ticker items."
  ],
  "a11y": {
    "role": "region",
    "keyboard": [],
    "focus": "Not focusable; items are presentational.",
    "labeling": "Region label names the feed; trend arrows have text alternatives.",
    "wcag": [
      "1.1.1",
      "2.2.2"
    ]
  },
  "responsive": {
    "strategy": "Horizontal scroll strip at all breakpoints.",
    "breakpoints": {
      "compact": "Scrollable strip.",
      "medium": "Scrollable strip.",
      "large": "Scrollable strip."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "ticker",
    "states": [
      "default",
      "empty"
    ],
    "intents": [
      "notify-status"
    ]
  }
}

.cu-ticker {
  display: block;
  border-block: 1px solid var(--cu-color-border-default);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  overflow: hidden;
}

.cu-ticker__strip {
  display: flex;
  gap: var(--cu-space-3);
  list-style: none;
  margin: 0;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  overflow-x: auto;
}

.cu-ticker__item {
  display: inline-flex;
  align-items: baseline;
  gap: var(--cu-space-1);
  white-space: nowrap;
}

.cu-ticker__value {
  font-weight: 600;
}

.cu-ticker__trend--up {
  color: color-mix(in srgb, var(--cu-color-palette-brand) 60%, green);
}

.cu-ticker__trend--down {
  color: color-mix(in srgb, var(--cu-color-palette-brand) 60%, red);
}

.cu-ticker__trend-text {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

import './styles.css'

export interface TickerItem {
  id: string
  label: string
  value: string
  trend?: 'up' | 'down' | 'flat'
}

export interface TickerProps {
  items: TickerItem[]
  label?: string
  className?: string
}

const TREND_GLYPH = { up: '▲', down: '▼', flat: '→' } as const

export function Ticker({ items, label = 'Ticker', className }: TickerProps) {
  const classes = ['cu-ticker', className].filter(Boolean).join(' ')
  return (
    <section
      className={classes}
      aria-label={label}
      data-ai-role="ticker" data-ai-intent="notify-status"
      data-ai-state={items.length === 0 ? 'empty' : 'default'}
    >
      <ul className="cu-ticker__strip">
        {items.map((item) => (
          <li key={item.id} className="cu-ticker__item">
            <span className="cu-ticker__label">{item.label}</span>
            <span className="cu-ticker__value">{item.value}</span>
            {item.trend ? (
              <span className={'cu-ticker__trend cu-ticker__trend--' + item.trend}>
                <span aria-hidden="true">{TREND_GLYPH[item.trend]}</span>
                <span className="cu-ticker__trend-text">{item.trend}</span>
              </span>
            ) : null}
          </li>
        ))}
      </ul>
    </section>
  )
}
